let big = 1
for i = 1 to 400 { big = big * 10 }
print(big % 7, big // 10 > 0, big - big, big * big > big, (big * 10) / big, big / big)

let big = 1
for i = 1 to 400 { big = big * 10 }
print(big + 0.5)

let big = 1
for i = 1 to 400 { big = big * 10 }
print(big / 3)

let big = 1
for i = 1 to 400 { big = big * 10 }
print(big // 3 > 0, big % 3, (big * big) // big == big)

let inf = num("1" + "0" * 400 + ".0")
let nan = inf - inf
print(nan == nan, nan != nan, nan < 1, nan > 1, nan <= nan)

let trail = []
def t(v) { append(trail, v)
return v }
let r = t(1) + t(2) * t(3) - t(4)
let l = [t(5), t(6)]
let d = {a: t(7), b: t(8)}
print(trail)

let d = {}
for i = 0 to 20 { d["k" + str(i)] = i * i }
let total = 0
for k, v in d { total = total + v }
print(total, keys(d)[0], keys(d)[20], len(d))

def f(n) { if n == 0 { return 0 }
return 1 + f(n - 1) }
print(f(40))
